CREATE FUNCTION app.guided_project_scope(actor uuid,sid uuid,pid uuid) RETURNS app.projects LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,app AS $$
DECLARE a app.users;p app.projects;
BEGIN
 a:=app.assignment_principal(actor,sid);
 SELECT * INTO p FROM app.projects WHERE id=pid AND university_id=a.university_id AND assignment_managed;
 IF p.id IS NULL OR NOT (a.role_code='university_admin' OR (a.role_code='faculty_supervisor' AND p.supervisor_id=actor) OR (a.role_code='student' AND EXISTS(SELECT 1 FROM app.project_authors WHERE project_id=pid AND user_id=actor))) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='FORBIDDEN';END IF;
 RETURN p;
END $$;
CREATE FUNCTION app.guided_project_person(actor uuid,pid uuid,uid uuid,admin boolean) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,app AS $$
 SELECT jsonb_build_object('id',u.id,'name',u.full_name,'email',CASE WHEN admin OR u.id=actor THEN u.email ELSE NULL END,'department',d.code,'role',u.role_code,'status',u.account_status,'setupComplete',EXISTS(SELECT 1 FROM app.account_lifecycle WHERE user_id=u.id AND purpose='activation' AND consumed_at IS NOT NULL),'mail',CASE WHEN admin THEN (SELECT jsonb_build_object('id',e.id,'state',CASE WHEN e.expires_at<=app.lifecycle_now() AND e.state IN ('queued','sending','failed','unknown') THEN 'expired' ELSE e.state END,'canRetry',e.state IN ('failed','unknown') AND e.attempts<10 AND e.manual_retries<1 AND e.ciphertext IS NOT NULL AND e.expires_at>app.lifecycle_now() AND EXISTS(SELECT 1 FROM app.account_lifecycle l WHERE l.id=e.lifecycle_id AND l.consumed_at IS NULL AND l.revoked_at IS NULL AND l.expires_at>app.lifecycle_now())) FROM app.account_email_outbox e JOIN app.account_lifecycle l ON l.id=e.lifecycle_id WHERE e.user_id=u.id AND e.purpose='ACCOUNT_SETUP' ORDER BY e.created_at DESC,e.id DESC LIMIT 1) ELSE NULL END)
 FROM app.users u LEFT JOIN app.departments d ON d.id=u.department_id WHERE u.id=uid;
$$;
CREATE FUNCTION app.guided_project_record(actor uuid,sid uuid,pid uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,app AS $$
DECLARE a app.users;p app.projects;result jsonb;admin boolean;
BEGIN
 p:=app.guided_project_scope(actor,sid,pid);a:=app.assignment_principal(actor,sid);admin:=a.role_code='university_admin';
 SELECT jsonb_build_object('id',p.id,'title',coalesce(v.title,''),'department',d.code,'departmentId',d.id,'year',coalesce(v.academic_year,''),'status',v.status,'revision',p.row_version,'version',v.id,'university',un.name_en,'universityAr',un.name_ar,'locked',EXISTS(SELECT 1 FROM app.project_submissions WHERE project_id=pid),'canManage',admin AND v.status NOT IN ('archived','rejected'),'isLead',EXISTS(SELECT 1 FROM app.project_authors WHERE project_id=pid AND user_id=actor AND is_team_lead),'isSupervisor',p.supervisor_id=actor,'supervisor',app.guided_project_person(actor,pid,p.supervisor_id,admin),'authors',(SELECT coalesce(jsonb_agg(app.guided_project_person(actor,pid,pa.user_id,admin)||jsonb_build_object('order',pa.author_order,'lead',pa.is_team_lead) ORDER BY pa.author_order),'[]') FROM app.project_authors pa WHERE pa.project_id=pid),'history',CASE WHEN admin THEN coalesce((SELECT jsonb_agg(x) FROM (SELECT action,reason,occurred_at AS at FROM app.audit_logs WHERE project_id=pid AND (action LIKE 'assignment.%' OR action LIKE 'project.onboarding.%') ORDER BY occurred_at DESC,id DESC LIMIT 20) x),'[]'::jsonb) ELSE '[]'::jsonb END) INTO result FROM app.project_versions v JOIN app.departments d ON d.id=p.department_id JOIN app.universities un ON un.id=p.university_id WHERE v.id=p.current_version_id;
 IF result IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='FORBIDDEN';END IF;RETURN result;
END $$;
CREATE FUNCTION app.guided_project_list(actor uuid,sid uuid,q text,filter_status text,filter_department text,filter_year text,page integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,app AS $$
DECLARE a app.users;result jsonb;total integer;depts jsonb;years jsonb;
BEGIN
 a:=app.assignment_principal(actor,sid);
 IF q IS NULL OR char_length(q)>200 OR page IS NULL OR page NOT BETWEEN 1 AND 10000 OR filter_status IS NULL OR filter_status NOT IN ('','draft','pending_review','revision_required','archived','rejected') OR filter_department IS NULL OR filter_department NOT IN ('','CS','IS','CE') OR filter_year IS NULL OR (filter_year<>'' AND (filter_year!~'^[0-9]{4}–[0-9]{4}$' OR right(filter_year,4)::integer<>left(filter_year,4)::integer+1)) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='INVALID_FILTER';END IF;
 WITH permitted AS (SELECT p.id,p.supervisor_id,p.department_id FROM app.projects p WHERE p.assignment_managed AND p.university_id=a.university_id AND (a.role_code='university_admin' OR (a.role_code='faculty_supervisor' AND p.supervisor_id=actor) OR (a.role_code='student' AND EXISTS(SELECT 1 FROM app.project_authors WHERE project_id=p.id AND user_id=actor)))), records AS (SELECT p.id,coalesce(v.title,'') AS title,d.code AS department,coalesce(v.academic_year,'') AS year,v.status,u.full_name AS supervisor,(SELECT count(*)::int FROM app.project_authors WHERE project_id=p.id) AS "authorCount" FROM permitted p JOIN app.projects pp ON pp.id=p.id JOIN app.project_versions v ON v.id=pp.current_version_id JOIN app.departments d ON d.id=p.department_id JOIN app.users u ON u.id=p.supervisor_id), filtered AS (SELECT * FROM records WHERE (q='' OR strpos(lower(title||' '||department||' '||year),lower(q))>0) AND (filter_status='' OR status=filter_status) AND (filter_department='' OR department=filter_department) AND (filter_year='' OR year=filter_year))
 SELECT (SELECT count(*)::int FROM filtered),(SELECT coalesce(jsonb_agg(x),'[]') FROM (SELECT * FROM filtered ORDER BY lower(title),id LIMIT 20 OFFSET (page-1)*20) x),(SELECT coalesce(jsonb_agg(code),'[]') FROM (SELECT DISTINCT department AS code FROM records ORDER BY department) x),(SELECT coalesce(jsonb_agg(year),'[]') FROM (SELECT DISTINCT year FROM records WHERE year<>'' ORDER BY year DESC) x) INTO total,result,depts,years;
 RETURN jsonb_build_object('rows',result,'total',total,'page',page,'departments',depts,'years',years);
END $$;
REVOKE ALL ON FUNCTION app.guided_project_scope(uuid,uuid,uuid),app.guided_project_person(uuid,uuid,uuid,boolean) FROM PUBLIC,capstone_runtime,capstone_jobs;
REVOKE ALL ON FUNCTION app.guided_project_record(uuid,uuid,uuid),app.guided_project_list(uuid,uuid,text,text,text,text,integer) FROM PUBLIC,capstone_jobs;
GRANT EXECUTE ON FUNCTION app.guided_project_record(uuid,uuid,uuid),app.guided_project_list(uuid,uuid,text,text,text,text,integer) TO capstone_runtime;
